-- Ledger-integrity: exclude voided/cancelled payments from the Power BI payment views.
-- Generated 2026-09-17 from the live definitions on the prod copy; each view is
-- recreated unchanged except for one added predicate on the payment status. A voided payment
-- (auditor soft-delete rule) has its ledger entries reversed and must not count as spent,
-- collected, outstanding or late. Unpaid drafts stay (they are reported as commitments).
-- Apply BEFORE deploying the void feature. Idempotent (CREATE OR REPLACE).
-- Not touched (already filter on a positive status): fact_project_expenses, fact_project_directpayments,
-- fact_nonproject_commitments, fact_apartment_* rows keyed on = 'PMNT_RECEIVED'.

-- payments: added WHERE
CREATE OR REPLACE VIEW `payments` AS select `p`.`PAYMENT_ID` AS `PaymentId`,`p`.`AMOUNT` AS `Amount`,`p`.`ACTUAL_CURRENCY_AMOUNT` AS `ActualAmount`,coalesce(`p`.`CURRENCY_UOM_ID`,'EGP') AS `CurrencyUomId`,`p`.`PARTY_ID_FROM` AS `PartyIdFrom`,`pf`.`DESCRIPTION` AS `PartyNameFrom`,`p`.`PARTY_ID_TO` AS `PartyIdTo`,coalesce(`pt`.`DESCRIPTION`,(case when (`p`.`PARTY_ID_TO` = 'Company') then 'Company' else `p`.`PARTY_ID_TO` end),'Unknown') AS `PartyNameTo`,`p`.`PAYMENT_TYPE_ID` AS `PaymentTypeId`,`p`.`SALES_REQUEST_ID` AS `SalesRequestId`,`pt_type`.`DESCRIPTION` AS `PaymentTypeDescription`,`pt_type`.`DESCRIPTION_ARABIC` AS `PaymentTypeDescriptionArabic`,`p`.`PAYMENT_METHOD_TYPE_ID` AS `PaymentMethodTypeId`,`pmt_type`.`DESCRIPTION` AS `PaymentMethodTypeName`,`pmt_type`.`DESCRIPTION_ARABIC` AS `PaymentMethodTypeNameArabic`,`p`.`PAYMENT_REF_NUM` AS `PaymentRefNum`,`p`.`PAYMENT_METHOD_ID` AS `PaymentMethodId`,`pm`.`DESCRIPTION` AS `PaymentMethodName`,`prod`.`PRODUCT_ID` AS `ProductId`,`prod`.`BUILDING_NUMBER` AS `BuildingNumber`,`p`.`WORK_EFFORT_ID` AS `ProjectId`,`we`.`PROJECT_NAME` AS `ProjectName`,`p`.`COST_CENTER_ID` AS `CostCenterId`,`cc`.`DESCRIPTION` AS `CostCenterName`,`opp`.`ORDER_ID` AS `OrderId`,`p`.`STATUS_ID` AS `StatusId`,`si`.`DESCRIPTION` AS `StatusNameEnglish`,`si`.`DESCRIPTION_ARABIC` AS `StatusNameArabic`,`p`.`EFFECTIVE_DATE` AS `EffectiveDate`,(to_days(`p`.`EFFECTIVE_DATE`) - to_days(curdate())) AS `DaysUntilDue`,(case when ((`p`.`STATUS_ID` = 'PMNT_RECEIVED') or (`p`.`STATUS_ID` <> 'PMNT_NOT_PAID')) then 'Received' when (`p`.`EFFECTIVE_DATE` >= curdate()) then 'Upcoming' when ((to_days(curdate()) - to_days(`p`.`EFFECTIVE_DATE`)) between 1 and 30) then 'Late (1-30 Days)' when ((to_days(curdate()) - to_days(`p`.`EFFECTIVE_DATE`)) between 31 and 90) then 'Late (31-90 Days)' else 'Late (Over 90 Days)' end) AS `OverdueBucket`,(case when (`p`.`STATUS_ID` <> 'PMNT_NOT_PAID') then `si`.`DESCRIPTION_ARABIC` else (case when ((to_days(`p`.`EFFECTIVE_DATE`) - to_days(curdate())) < 0) then (case when (abs((to_days(`p`.`EFFECTIVE_DATE`) - to_days(curdate()))) <= 30) then concat((case when (`pt_type`.`PARENT_TYPE_ID` = 'DISBURSEMENT') then 'دفعة' else 'مستحق' end),' متأخرة منذ ',abs((to_days(`p`.`EFFECTIVE_DATE`) - to_days(curdate()))),' يوم') else concat((case when (`pt_type`.`PARENT_TYPE_ID` = 'DISBURSEMENT') then 'دفعة' else 'مستحق' end),' متأخرة جداً ','(الربع ',(case when (month(`p`.`EFFECTIVE_DATE`) between 1 and 3) then 'الأول' when (month(`p`.`EFFECTIVE_DATE`) between 4 and 6) then 'الثاني' when (month(`p`.`EFFECTIVE_DATE`) between 7 and 9) then 'الثالث' else 'الرابع' end),' ',year(`p`.`EFFECTIVE_DATE`),')') end) when ((to_days(`p`.`EFFECTIVE_DATE`) - to_days(curdate())) = 0) then concat((case when (`pt_type`.`PARENT_TYPE_ID` = 'DISBURSEMENT') then 'دفعة مستحقة' else 'مستحق' end),' اليوم') when ((to_days(`p`.`EFFECTIVE_DATE`) - to_days(curdate())) = 1) then concat((case when (`pt_type`.`PARENT_TYPE_ID` = 'DISBURSEMENT') then 'دفعة مستحقة' else 'مستحق' end),' غداً') when ((to_days(`p`.`EFFECTIVE_DATE`) - to_days(curdate())) <= 3) then concat((case when (`pt_type`.`PARENT_TYPE_ID` = 'DISBURSEMENT') then 'دفعة مستحقة' else 'مستحق' end),' بعد ',(to_days(`p`.`EFFECTIVE_DATE`) - to_days(curdate())),' أيام') when ((to_days(`p`.`EFFECTIVE_DATE`) - to_days(curdate())) <= 7) then concat((case when (`pt_type`.`PARENT_TYPE_ID` = 'DISBURSEMENT') then 'دفعة مستحقة' else 'مستحق' end),' هذا الأسبوع') when ((to_days(`p`.`EFFECTIVE_DATE`) - to_days(curdate())) <= 30) then concat((case when (`pt_type`.`PARENT_TYPE_ID` = 'DISBURSEMENT') then 'دفعة مستحقة' else 'مستحق' end),' خلال الشهر') when ((to_days(`p`.`EFFECTIVE_DATE`) - to_days(curdate())) <= 90) then concat((case when (`pt_type`.`PARENT_TYPE_ID` = 'DISBURSEMENT') then 'دفعة مستحقة' else 'مستحق' end),' خلال 3 أشهر ','(الربع ',(case when (month(`p`.`EFFECTIVE_DATE`) between 1 and 3) then 'الأول' when (month(`p`.`EFFECTIVE_DATE`) between 4 and 6) then 'الثاني' when (month(`p`.`EFFECTIVE_DATE`) between 7 and 9) then 'الثالث' else 'الرابع' end),' ',year(`p`.`EFFECTIVE_DATE`),')') else concat((case when (`pt_type`.`PARENT_TYPE_ID` = 'DISBURSEMENT') then 'دفعة مستحقة' else 'مستحق' end),' لاحقاً ','(الربع ',(case when (month(`p`.`EFFECTIVE_DATE`) between 1 and 3) then 'الأول' when (month(`p`.`EFFECTIVE_DATE`) between 4 and 6) then 'الثاني' when (month(`p`.`EFFECTIVE_DATE`) between 7 and 9) then 'الثالث' else 'الرابع' end),' ',year(`p`.`EFFECTIVE_DATE`),')') end) end) AS `DueStatusArabic`,(case when (`pt_type`.`PARENT_TYPE_ID` = 'DISBURSEMENT') then 1 else 0 end) AS `IsDisbursement`,(case when (`pt_type`.`PARENT_TYPE_ID` = 'DISBURSEMENT') then `p`.`PARTY_ID_FROM` else `p`.`PARTY_ID_TO` end) AS `OrganizationPartyId`,(case when (`pt_type`.`PARENT_TYPE_ID` = 'DISBURSEMENT') then 'Outbound' when (`p`.`PARTY_ID_TO` = 'Company') then 'Inbound' else 'Unknown' end) AS `PaymentDirection`,`p`.`COMMENTS` AS `Comments`,`p`.`ChequeNumber` AS `ChequeNumber`,`p`.`ChequeDate` AS `ChequeDate`,`p`.`OVERRIDE_GL_ACCOUNT_ID` AS `OverrideGlAccountId`,`p`.`CREATED_STAMP` AS `CreatedDate`,`p`.`PAYMENT_PREFERENCE_ID` AS `PaymentPreferenceId` from ((((((((((((`payment` `p` left join `party` `pf` on((`p`.`PARTY_ID_FROM` = `pf`.`PARTY_ID`))) left join `party` `pt` on((`p`.`PARTY_ID_TO` = `pt`.`PARTY_ID`))) left join `payment_method` `pm` on((`p`.`PAYMENT_METHOD_ID` = `pm`.`PAYMENT_METHOD_ID`))) left join `cost_center` `cc` on((`p`.`COST_CENTER_ID` = `cc`.`COST_CENTER_ID`))) left join `status_item` `si` on((`p`.`STATUS_ID` = `si`.`STATUS_ID`))) left join `work_effort` `we` on((`p`.`WORK_EFFORT_ID` = `we`.`WORK_EFFORT_ID`))) left join `payment_type` `pt_type` on((`p`.`PAYMENT_TYPE_ID` = `pt_type`.`PAYMENT_TYPE_ID`))) left join `payment_method_type` `pmt_type` on((`p`.`PAYMENT_METHOD_TYPE_ID` = `pmt_type`.`PAYMENT_METHOD_TYPE_ID`))) left join `order_payment_preference` `opp` on((`p`.`PAYMENT_PREFERENCE_ID` = `opp`.`ORDER_PAYMENT_PREFERENCE_ID`))) left join `order_header` `ord` on((`opp`.`ORDER_ID` = `ord`.`ORDER_ID`))) left join `sales_request` `sr` on((`p`.`SALES_REQUEST_ID` = `sr`.`SALES_REQUEST_ID`))) left join `product` `prod` on((`sr`.`PRODUCT_ID` = `prod`.`PRODUCT_ID`))) where (`p`.STATUS_ID is null or `p`.STATUS_ID not in ('PMNT_VOID','PMNT_CANCELLED')) order by `p`.`EFFECTIVE_DATE` desc,`p`.`PAYMENT_ID` desc;

-- payments_2: added WHERE
